WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY method, order_id ORDER BY paid_at, id) AS rank_in_group FROM payments QUALIFY rank_in_group = 1) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, status, COUNT_IF(method = 'paypal') AS paypal_events, ROUND(AVG(amount), 2) AS avg_amount, SIZE(COLLECT_SET(status)) AS num_status FROM latest GROUP BY DATE_TRUNC('YEAR', paid_at), status
